def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    # The long solid line is the divider; the most common remaining color is
    # the field, and all other cells form the figure to slide against it.
    div = 2
    bg = max((x for x in counts if x != div), key=lambda x: counts[x])
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (bg, div)]
    if not points:
        return out
    rows = [r for r in range(h) if all(x == div for x in grid[r])]
    if rows:
        d = rows[0]
        r0 = min(r for r, c in points)
        r1 = max(r for r, c in points)
        shift = d - 1 - r1 if r1 < d else d + 1 - r0
        # Clear original figure, then translate it as one rigid pattern.
        for r, c in points:
            out[r][c] = bg
        for r, c in points:
            out[r + shift][c] = grid[r][c]
        line = r0 + shift - 1 if r1 < d else r1 + shift + 1
        if 0 <= line < h:
            out[line] = [8] * w
    else:
        cols = [c for c in range(w) if all(grid[r][c] == div for r in range(h))]
        if cols:
            d = cols[0]
            c0 = min(c for r, c in points)
